48	/**
49	 * `/app?run=<id>` scopes this page to its own server-side state, so Kane
50	 * objectives running in parallel don't share one workspace. Without it the
51	 * page uses the shared state, as before.
52	 */
53	function runId(): string | null {
54	  if (typeof window === "undefined") return null;
55	  const run = new URLSearchParams(window.location.search).get("run");
56	  return run && /^[A-Za-z0-9_-]{1,64}$/.test(run) ? run : null;
57	}
58	
59	/** Workspace state changes on every write, so never answer from the browser's HTTP cache. */
60	async function call<T>(path: string, method: "GET" | "POST" = "GET"): Promise<T> {
61	  const run = runId();
62	  const url = run ? `${path}?run=${encodeURIComponent(run)}` : path;
63	  const res = await fetch(url, { method, cache: "no-store" });
64	  if (!res.ok) throw new Error(`${method} ${path} → ${res.status}`);
65	  return (await res.json()) as T;
66	}
