133	    });
134	
135	  const copySecret = async () => {
136	    if (!secret) return;
137	    try {
138	      await navigator.clipboard.writeText(secret);
139	      setCopied(true);
140	    } catch {
141	      /* clipboard blocked; the key is still selectable */
