164	            <span className="sm:hidden">Guarded by Driftor.</span>
165	          </span>
166	          <span className="flex shrink-0 items-center gap-4">
167	            <Link href="/hud" className="hover:text-white">
168	              Traces
169	            </Link>
170	            <Link href="/" className="text-white hover:underline">
171	              ← Driftor
172	            </Link>
