260	            {/* Metrics */}
261	            <div
262	              id="quota"
263	              className="mt-6 grid grid-cols-2 lg:grid-cols-4 gap-px overflow-hidden rounded-lg border border-cs-line bg-cs-line scroll-mt-6"
264	            >
265	              <div className="p-4 bg-white">
266	                <div className="text-xs text-cs-sub">Active keys</div>
267	                <div data-testid="key-count" className="mt-1 text-xl font-semibold tabular-nums">
268	                  {state ? `${state.keys.length} Keys` : "…"}
