            <nav
              id="mobile-menu"
              aria-label="Sections"
              className={`absolute inset-x-0 top-full z-40 h-[calc(100vh-5.25rem)] bg-white/95 px-4 py-3 flex flex-col gap-1 transition-opacity ${
