      <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true">
        <path d="M3 13a4 4 0 0 1 3.2-3.9A5 5 0 0 1 16 10a3 3 0 0 1 0 6H6a3 3 0 0 1-3-3z" fill="#2443B8" />
      </svg>
      <span className="font-semibold tracking-tight">CloudScale</span>
    </div>
  );
}

function ago(iso: string, now: number) {
  const s = Math.max(0, Math.round((now - new Date(iso).getTime()) / 1000));
  if (s < 10) return "just now";
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.round(s / 60)} min ago`;
  if (s < 86400) return `${Math.round(s / 3600)} h ago`;
  return `${Math.round(s / 86400)} d ago`;
}

/**
 * `/app?run=<id>` scopes this page to its own server-side state, so Kane
 * objectives running in parallel don't share one workspace. Without it the
 * page uses the shared state, as before.
 */
function runId(): string | null {
  if (typeof window === "undefined") return null;
  const run = new URLSearchParams(window.location.search).get("run");
  return run && /^[A-Za-z0-9_-]{1,64}$/.test(run) ? run : null;
}

/** Workspace state changes on every write, so never answer from the browser's HTTP cache. */
async function call<T>(path: string, method: "GET" | "POST" = "GET", body?: unknown): Promise<T> {
  const run = runId();
  const url = run ? `${path}?run=${encodeURIComponent(run)}` : path;
  const res = await fetch(url, {
    method,
    cache: "no-store",
    ...(body === undefined ? {} : { headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }),
  });
  if (!res.ok) throw new Error(`${method} ${path} → ${res.status}`);
  return (await res.json()) as T;
}

/** Re-render periodically so relative times stay current. */
function useNow(ms = 15_000) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), ms);
    return () => clearInterval(t);
  }, [ms]);
  return now;
}

